import type { ReactNode } from 'react';
import { StrictMode, useId } from 'react';
import { AppProviders } from './contexts/AppProviders.js';
import { initializeBrowserGlobals } from './router/init/initializeBrowserGlobals.ts';

initializeBrowserGlobals();

export function AppRoot({ children }: { children: ReactNode }) {
  return (
    <StrictMode>
      <AppProviders>{children}</AppProviders>
    </StrictMode>
  );
}

export function Layout({ children }: { children: ReactNode }) {
  return <>{children}</>;
}

export function HydrateFallback() {
  const containerId = useId();
  const statusId = useId();

  return (
    <div
      id={containerId}
      style={{
        position: 'fixed',
        inset: 0,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: '#ffffff',
      }}
    >
      <output
        id={statusId}
        aria-live="polite"
        aria-label="Loading"
        style={{
          width: '32px',
          height: '32px',
          border: '3px solid #e0e0e0',
          borderTopColor: '#1976d2',
          borderRadius: '50%',
          animation: 'hdb-spin 0.8s linear infinite',
          display: 'inline-block',
        }}
      >
        <span style={{ position: 'absolute', opacity: 0, pointerEvents: 'none' }}>Loading</span>
      </output>
      <style>{`
        @keyframes hdb-spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
}

export function ErrorBoundary() {
  return (
    <div
      style={{
        padding: '20px',
        color: 'red',
        fontFamily: 'monospace',
        backgroundColor: '#fff5f5',
        border: '1px solid #fecaca',
        borderRadius: '8px',
        margin: '20px',
      }}
    >
      <h1 style={{ color: '#dc2626', marginBottom: '20px' }}>Application Error</h1>
      <p>Please check the console for additional details.</p>
    </div>
  );
}

export default AppRoot;
